local UIModule = CS.Engine.UI.UIModule

---@type GroceryConstants
local GroceryConstants = import('Game.Grocery.GroceryConstants')

---@class GroceryUtils
local GroceryUtils = Class('GroceryUtils')

---打开杂货铺首页
---@param groceryType GroceryConstants.GroceryType | nil 
---@param excludeIds  table   互斥页面
---@param exParameter table | nil 额外参数
---@param isStack     boolean 是否是导航条的跳转
function GroceryUtils.OpenGroceryStore(groceryType, excludeIds, exParameter, isStack)
    isStack = (not checkBool(isStack)) ---初始为true入栈的操作
    local parameters = {}
    parameters.exParameter = exParameter
    parameters.groceryType = groceryType
    return UIModule.OpenDialog({ id = Constants.UITypeIds.GroceryDialog, parameters = parameters }, excludeIds, isStack)
end

---获取商城道具背景
---@param quality Constants.QualityType 道具品质
function GroceryUtils.GetGoodsBgByQuality(quality)
    local bg = "UIAtlas/common2/common_frame_goods_1_s.png"
    if (quality == Constants.QualityType.Whit) then
        bg = "UIAtlas/common2/common_frame_goods_1_s.png"
    elseif (quality == Constants.QualityType.Green) then
        bg = "UIAtlas/common2/common_frame_goods_2_s.png"
    elseif (quality == Constants.QualityType.Blue) then
        bg = "UIAtlas/common2/common_frame_goods_3_s.png"
    elseif (quality == Constants.QualityType.Purple) then
        bg = "UIAtlas/common2/common_frame_goods_4_s.png"
    elseif (quality == Constants.QualityType.Orange) then
        bg = "UIAtlas/common2/common_frame_goods_5_s.png"
    elseif (quality == Constants.QualityType.Red) then
        bg = "UIAtlas/common2/common_frame_goods_6_s.png"
    elseif (quality == Constants.QualityType.Colours) then
        bg = "UIAtlas/common2/common_frame_goods_6_s.png"
    end
    return bg
end

---判断商品是否免费
function GroceryUtils.JudgeProductIsFree(product)
    return checkInt(product.tab) == 9 and next(checkTable(product.prices)) == nil
end

---商品是否售罄
function GroceryUtils.ProductIsSoldOut(product)
    if not isSet(product, "currentStock") then
        return false
    end
    if product.stock ~= -1 then
        return product.currentStock == 0
    else
        return false
    end
end
---商品是否拥有后不让购买
function GroceryUtils.ProductIsOnly(product)
    if not isSet(product, "only") or product.only ~= 1 then
        return false
    end
    local num = GoodsUtils.GetThingNo(product.goodsId)
    return checkNumber(num) > 0
end

---商品是否锁定
function GroceryUtils.ProductIsLocked(product)
    if not isSet(product, "unlock") then
        return false
    end

    --p.targetType
    --p.targetId =
    --p.targetNum 
    local isLocked = false
    local lockedDescr = ''
    for i = 1, #product.unlock do
        isLocked = isLocked or not GameUtils.IsUnlockedSingle(product.unlock[i].targetType, product.unlock[i].targetNum, product.unlock[i].targetId)
        if isLocked then
            lockedDescr = GameUtils.GetUnlockDescr(tostring(product.unlock[i].targetType), tostring(product.unlock[i].targetNum),  tostring(product.unlock[i].targetId))
            break
        end
    end
    return isLocked, lockedDescr
end

---格式化时间
function GroceryUtils.FormatTime(second)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("_num1_天_num2_小时", { _num1_ = d, _num2_ = h - d * 24 })
    end
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    return h .. ":" .. m .. ":" .. s
end

---通过硬币品质获取图
---@param quality integer 品质
function GroceryUtils.GetCoinImageByQuality(quality)
    local goodsId = GroceryConstants.CoinQuality2GoodsId[checkInt(quality)]
    local goodsVo = GoodsConfMgr:GetGoodsVoById(goodsId)
