    return goodsVo.photoPath
end

---通过杂货铺类型获取商店类型表中配置的显示货币（需在GroceryNodeConfigs中配置shopId）
---@param groceryType GroceryConstants.GroceryType
function GroceryUtils.GetCurrencyByGroceryType(groceryType)
    local config = GroceryConstants.GroceryNodeConfigs[groceryType]
    if not config then return end

    local cfVo = CfUtils.GetCfVo(AutoIds.IdSetting601, "StoreGeneralVo", checkInt(config.shopId))
    if  not cfVo then return end
    
    return checkTable(cfVo.token)
end

---通过杂货铺类型获取商店类型表中配置的商店名称（需在GroceryNodeConfigs中配置shopId）
---@param groceryType GroceryConstants.GroceryType
function GroceryUtils.GetTabNameByGroceryType(groceryType)
    if groceryType == GroceryConstants.GroceryType.Equipment then
        return localize("装备抽取")
    end
    
    local config = GroceryConstants.GroceryNodeConfigs[groceryType]
    if not config then return end

    local cfVo = CfUtils.GetCfVo(AutoIds.IdSetting601, "StoreGeneralVo", checkInt(config.shopId))
    if  not cfVo then return end

    return cfVo.tabName
end

---@param drawType integer @ 1：单抽、2：十连
---@param equipGroceryData table @ 装备卡池数据
---@return table[]
function GroceryUtils.GetCallEquipConsumeDatas(callType, equipGroceryData)
    local consumeDataList = {}
    local equipCallTimes  = callType == 2 and 10 or 1
    local consumePropData = {goodsId = 0, num = 0}
    local consumeGoldData = {goodsId = 0, num = 0}
    local oneConsumeData  = checkTable(equipGroceryData.oneConsume)
    local tenConsumeData  = checkTable(equipGroceryData.tenConsume)

    -- 单抽模式 并且 有免费次数时，无消耗
    if callType == 1 and checkInt(equipGroceryData.dailyFreeCall) == 1 then  -- 1可抽取 2已抽取
    else
        -- 是否有代币模式
        ---@type GroceryEquipmentVo
        local equipmentVo = CfUtils.GetCfVo(AutoIds.IdSetting3075, "GroceryEquipmentVo", equipGroceryData.poolId) or {}
        if checkInt(equipmentVo.substituteProp) > 0 then
            local callPropId  = checkInt(equipmentVo.substituteProp)
            local havePropNum = GoodsUtils.GetThingNo(callPropId)
            consumePropData.goodsId = callPropId
            consumePropData.num     = math.min(equipCallTimes, havePropNum)
        end
    
        -- 是否使用了代币
        if consumePropData.num > 0 then
            table.insert(consumeDataList, consumePropData)
    
            -- 部分使用了代币，剩下的使用单抽消耗补足（1个道具抵消1次消耗）
            if consumePropData.num < equipCallTimes then
                consumeGoldData.goodsId = oneConsumeData.goodsId
                consumeGoldData.num     = oneConsumeData.num * (equipCallTimes - consumePropData.num)
                table.insert(consumeDataList, consumeGoldData)
            end
            
        else
            -- 全部使用货币抽
            consumeGoldData = (callType == 2) and tenConsumeData or oneConsumeData
            table.insert(consumeDataList, consumeGoldData)
        end
    end

    return consumeDataList
end

---检查道具是否锁定显示
function GroceryUtils:CheckItemUnlockShow(itemData)
    if checkInt(itemData) == 1 then
        return true
    end
    
    return not GroceryUtils.ProductIsLocked(itemData)
end

return GroceryUtils